import { renderComponent } from '@ember/renderer';
import { getComponentTemplate } from '@ember/component';
import { or, and, not, notEq, eq } from 'ember-truth-helpers';
import EmberBasicDropdown from 'ember-basic-dropdown/components/basic-dropdown';
import PowerSelectPlaceholder from 'ember-power-select/components/power-select/placeholder';
import { ensureSafeComponent } from '@embroider/util';
import buildOwner from '../internals/build-owner';
import PowerSelectOptionsComponent from 'ember-power-select/components/power-select/options';
import PowerSelectBeforeOptionsComponent from 'ember-power-select/components/power-select/before-options';
import PowerSelectTriggerComponent from 'ember-power-select/components/power-select/trigger';
import PowerSelectNoMatchesMessageComponent from 'ember-power-select/components/power-select/no-matches-message';

let _owner = buildOwner()
_owner.register('helper:or', or);
_owner.register('helper:and', and);
_owner.register('helper:not', not);
_owner.register('helper:not-eq', notEq);
_owner.register('helper:eq', eq);
_owner.register('helper:ensure-safe-component', ensureSafeComponent);
_owner.register('helper:assign', Object.assign);

_owner.register(
  'config:environment',
  {},
  { instantiate: false },
);

_owner.register('component:basic-dropdown', EmberBasicDropdown);
_owner.register('component:power-select/placeholder', PowerSelectPlaceholder);

_owner.register('component:power-select/before-options', PowerSelectBeforeOptionsComponent);
_owner.register('component:power-select/options', PowerSelectOptionsComponent);
_owner.register('component:power-select/trigger', PowerSelectTriggerComponent);
_owner.register('component:power-select/no-matches-message', PowerSelectNoMatchesMessageComponent);


export function defineEmberCustomElement(tagName, Component, options = {}) {
	const { attributes = [], callbackProps = [] } = options;

	class EmberCustomElement extends HTMLElement {
    constructor() {
      super();
      this._renderResult = null;
      this._callbacks = Object.create(null);
    }

		static get observedAttributes() {
			return attributes;
		}

		connectedCallback() {
			this._render();
		}

		attributeChangedCallback(name, oldValue, newValue) {
			if (oldValue === newValue) return;
			if (!this.isConnected) return;
			// this._render();
		}

		disconnectedCallback() {
			if (this._renderResult) {
				this._renderResult.destroy();
				this._renderResult = null;
			}
		}

		_buildArgs() {
			let args = {};

			// Atributos HTML -> args do componente
			for (let attr of attributes) {
				let value = this.getAttribute(attr);
				if (value === null) continue;

				if (value === 'true') {
					value = true;
				} else if (value === 'false') {
					value = false;
				}

				args[attr] = value;
			}

			// Propriedades de callback (funções) expostas no custom element
			// Sempre passamos pelo menos um no-op para evitar asserts de libs
			// que exigem a presença de um handler (caso de ember-power-select
			// com `@onChange`). Quando o usuário atribuir uma função real,
			// faremos um novo render com o handler correto.
			for (let prop of callbackProps) {
				let fn = this._callbacks && this._callbacks[prop];
				if (typeof fn === 'function') {
					args[prop] = fn;
				} else {
					args[prop] = () => {};
				}
			}

			return args;
		}

		_render() {
			if (this._renderResult) {
				this._renderResult.destroy();
				this._renderResult = null;
			}

      this._renderResult = renderComponent(Component, {
				into: this,
				args: this._buildArgs(),
        owner: _owner,
			});
		}
	}

	// Define dinamicamente propriedades de callback no prototype do custom element,
	// de forma que atribuir `element.onClick = fn` (por exemplo) reprocesse os args.
	for (let prop of callbackProps) {
		if (prop in EmberCustomElement.prototype) continue;

		Object.defineProperty(EmberCustomElement.prototype, prop, {
			get() {
				return this._callbacks && this._callbacks[prop];
			},
			set(value) {
				if (!this._callbacks) {
					this._callbacks = Object.create(null);
				}
				this._callbacks[prop] = value;

				if (this.isConnected) {
					this._render();
				}
			},
		});
	}

	if (!customElements.get(tagName)) {
		customElements.define(tagName, EmberCustomElement);
	}
}

