import EmberResolver from 'ember-resolver';
import buildRegistry from './build-registry';

function createDefaultResolver() {
	const emptyModuleRegistry = {
		moduleNames() {
			return [];
		},
		has() {
			return false;
		},
		get() {
			return undefined;
		},
	};

	const namespace = {
		modulePrefix: 'web-components',
	};

	return EmberResolver.create({
		_moduleRegistry: emptyModuleRegistry,
		namespace,
	});
}

export default function buildOwner(passedResolver) {
	let resolver = passedResolver;

	if (!resolver) {
		resolver = createDefaultResolver();
	}

	const { owner } = buildRegistry(resolver);

	return owner;
}
